const first = counter.increment();
 const second = counter.increment();
 try {
  assert.equal(releases.length, 2, 'both calls must reach their checkpoints');
  releases[0]();
  await first;
  releases[1]();
  await second;
 } finally {
  // Leave no checkpoint blocked even if a schedule assertion fails.
  for (const release of releases) release();
  await Promise.all([first, second]);
 }

